param([string]$RepoRoot=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path,[string]$RunId='aot_flow_part0_v27',[string]$OutputRoot='')
if(-not $OutputRoot){$OutputRoot=Join-Path $RepoRoot 'artifacts\route_b_official\aot_action_bank_flow_part0_v27_runner'}
$pidFile=Join-Path $OutputRoot "${RunId}_pid.txt";$metaFile=Join-Path $OutputRoot "${RunId}_meta.txt";$pidValue=if(Test-Path -LiteralPath $pidFile){Get-Content -LiteralPath $pidFile|Select-Object -First 1}else{''};$process=if($pidValue-match'^\d+$'){Get-CimInstance Win32_Process -Filter "ProcessId = $pidValue" -ErrorAction SilentlyContinue}else{$null}
if($process-and$process.CommandLine-like'*aot_action_bank_flow_recovery.py*'){Write-Host "RUNNING=true PID=$pidValue";Write-Host "PID_START=$([Management.ManagementDateTimeConverter]::ToDateTime($process.CreationDate).ToString('yyyy-MM-dd HH:mm:ss'))";Write-Host "PROCESS_COMMAND=$($process.CommandLine)"}else{Write-Host "NOT RUNNING PID=$pidValue"}
$summary=Join-Path $RepoRoot 'artifacts\route_b_official\aot_action_bank_flow_part0_v27\flow_recovery_summary.json';if(Test-Path -LiteralPath $summary){$value=Get-Content -LiteralPath $summary -Raw|ConvertFrom-Json;Write-Host 'done/total: 1/1';Write-Host "last output timestamp: $((Get-Item -LiteralPath $summary).LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'))";Write-Host "last completed unit: flow_recovery_summary";Write-Host ($value.counters|ConvertTo-Json -Compress)}else{Write-Host 'done/total: 0/1';Write-Host 'last output timestamp: none';Write-Host 'last completed unit: none'}
if(Test-Path -LiteralPath $metaFile){$meta=Get-Content -LiteralPath $metaFile;$meta|Where-Object{$_-like'stdout=*'-or$_-like'stderr=*'};foreach($line in $meta){if($line-like'stderr=*'){$path=$line.Substring(7);if(Test-Path -LiteralPath $path){Get-Content -LiteralPath $path -Tail 10}}}}
